package br.com.sistemacardapio.complemento;import java.math.BigDecimal;import java.util.UUID;import br.com.sistemacardapio.empresa.Empresa;import jakarta.persistence.*;
@Entity@Table(name="complemento")public class Complemento{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="empresa_id")private Empresa empresa;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="grupo_id")private GrupoComplemento grupo;@Column(nullable=false,length=120)private String nome;@Column(name="preco_adicional",nullable=false,precision=12,scale=2)private BigDecimal preco;@Column(nullable=false)private int ordem;@Column(nullable=false)private boolean ativo;protected Complemento(){}public Complemento(GrupoComplemento g,String n,BigDecimal p,int o){id=UUID.randomUUID();empresa=g.getEmpresa();grupo=g;atualizar(n,p,o,true);}public void atualizar(String n,BigDecimal p,int o,boolean a){nome=n.trim();preco=p;ordem=o;ativo=a;}public UUID getId(){return id;}public String getNome(){return nome;}public BigDecimal getPreco(){return preco;}public int getOrdem(){return ordem;}public boolean isAtivo(){return ativo;}}
